/** A story's prose in the requested language, falling back to Arabic. */
/**
 * The text to render: the English where this story has it and the reader asked
 * for English, the Arabic otherwise.
 *
 * These take the English text rather than a locale because the English no
 * longer travels inside the story — it lives in content/stories-en.ts and is
 * fetched only for a reader who is actually reading in English. Looking it up
 * is the caller's job, which useStoryText() in content/stories-english.ts does
 * once per page; passing `undefined` is how an Arabic reader asks for Arabic.
 */
export const storyTextFor = (story: Story, english?: StoryText): StoryText =>
  english ?? {
    title: story.title,
    hook: story.hook,
    events: story.events,
    lesson: story.lesson,
    next: story.next,
    quranProse: story.quranProse,
    challenge: story.challenge,
    reward: story.reward,
    arc: story.arc,
  };

/** The question and the medal, falling back to the Arabic where a chapter's
 *  translation has not landed yet. */
export const storyChallengeFor = (story: Story, english?: StoryText): StoryChallenge =>
  english?.challenge ?? story.challenge;

export const storyRewardFor = (story: Story, english?: StoryText): StoryReward =>
  english?.reward ?? story.reward;

/** The rest of the arc, or nothing where this story has not been rewritten to
 *  the standard yet. English falls back to the Arabic arc only when the English
 *  prose itself is falling back — so the arc and the prose never disagree. */
export const storyArcFor = (story: Story, english?: StoryText): StoryArc | undefined =>
  english ? english.arc : story.arc;

/**
 * Roughly how long this story takes a child to read, in minutes.
 *
 * Authored reading times go stale the moment anyone edits a paragraph, so this
 * counts the words that are actually on the page. 120 words a minute is slow
 * for an adult and about right for a seven-year-old reading aloud, and the
 * number is rounded up so it never promises less than it costs.
 */
export const storyMinutes = (story: Story, english?: StoryText): number => {
  const text = storyTextFor(story, english);
  const arc = storyArcFor(story, english);
  const parts = [
    text.hook, text.events, text.lesson, text.quranProse ?? "",
    arc?.setting ?? "", arc?.keyMoment ?? "", arc?.resolution ?? "",
    ...(arc?.lessons ?? []), arc?.think ?? "", arc?.tryToday ?? "",
  ];
  const words = parts.join(" ").trim().split(/\s+/).filter(Boolean).length;
  return Math.max(1, Math.ceil(words / 120));
};

/** Where a story's English text is filed in content/stories-en.ts. */
export const storyKey = (story: Story): string => `${story.chapter}/${story.slug}`;
